// Tauri 构建脚本：编译期读取 tauri.conf.json 并生成上下文（图标 / 窗口 / 协议）。
//
// 20261104 修复（updater 三命令在真机被 ACL 拒）：
//   注入脚本跑在 **https://chat.deepseek.com（远程 origin）**。Tauri v2 的 ACL 规则是
//   「远程内容默认碰不到任何自定义命令，除非显式配 remote capability 并授予命令权限」
//   （见 tauri-2.12.2/src/webview/mod.rs:2076-2108：`plugin_command.is_some() ||
//     has_app_acl_manifest || !is_local` 且 `invoke.acl.is_none()` → reject）。
//
//   而 **app 命令的权限标识必须先在这里声明才会生成**（否则 `permissions/app/autogenerated/`
//   下没有对应条目，capabilities 里无从引用 —— 构建期 `__app__-permission-files` = `[]` 即此）。
//   之前 `tauri_build::build()` 没声明任何命令，所以 `invoke('updater_check')` 在远程页
//   必然被拒，且 debug 构建给出的是「未授权」提示、release 构建给出
//   `Command updater_check not allowed by ACL` —— 这正是发布后真机验收抓到的缺陷。
//
// 声明的命令 = **所有会被远程聊天页调用的 app 命令**（含既有的窗口类命令：它们此前
// 只是没在远程页真机验证过；既然规矩是"远程默认全拒"，就得一并声明并授权）。
fn main() {
    tauri_build::try_build(
        tauri_build::Attributes::new().app_manifest(tauri_build::AppManifest::new().commands(&[
            // 窗口类（聊天页 / bot 页调用）
            "open_workbench",
            "focus_main_window",
            "open_bot_window",
            // 自动更新（update-card 调用）
            "updater_check",
            "updater_install",
            "updater_progress",
            // ⚠️ 2026-11-06 真机 P0（v0.14.8）：**下面这两条漏声明 = agent 通道全死**。
            //   机理：ACL 由真实 Tauri runtime 在 IPC 层强制；本列表是权限清单的**唯一生成源**
            //   （`permissions/autogenerated/<cmd>.toml` 由这里生成、`capabilities` 只能引用已生成的
            //   identifier）。没声明 ⇒ toml 不生成 ⇒ capabilities 无从放行 ⇒
            //   `invoke('studio_request_grant')` 直接抛 "Command … not allowed by ACL"。
            //   而**命令体根本不会执行**，所以函数内的四条失败分支日志与 `grant_log()` 全被绕过 ——
            //   「fail-visible 只在函数执行后生效」这个盲区正是这次「彻底静默」的成因。
            //   新增任何会被页面调用的 command，**必须同时**：① 加进本列表 ② 重新构建生成 toml
            //   ③ 在 `capabilities/default.json` 的 permissions 里引一条 `allow-<kebab>`。
            //   （Gate 已有守卫对账 ①②③，见 tools/audit/acl-contract-guard.ts。）
            "studio_request_grant",
            "studio_open_mcp_settings",
        ])),
    )
    .expect("failed to run tauri-build");
}
